use std::time::Instant;

pub struct RateLimiter {
    capacity: u32,
    tokens: f64,
    last: Instant,
}

impl RateLimiter {
    pub fn new(capacity: u32) -> Self {
        Self { capacity, tokens: capacity as f64, last: Instant::now() }
    }

    fn refill(&mut self) {
        let now = Instant::now();
        let gained = now.duration_since(self.last).as_secs_f64();
        self.tokens = (self.tokens + gained).min(self.capacity as f64);
        self.last = now;
    }

    pub fn try_acquire(&mut self) -> bool {
        self.refill();
        if self.tokens >= 1.0 {
            self.tokens -= 1.0;
            true
        } else {
            false
        }
    }
}

